import {generatedMap} from './generated-materials.mjs';
import {conformToTerrain} from './terrain-surface.mjs';
import * as T from './vendor/three.module.js';
const surfaceMaps=new Map();
function surfaceMap(name){if(surfaceMaps.has(name))return surfaceMaps.get(name);const original=generatedMap(name);if(!original)return null;const map=original.clone();map.channel=1;map.needsUpdate=true;surfaceMaps.set(name,map);return map;}
export function createTerrainPath(points,width,height,color='#92704d',options={}){
const root=new T.Group(),strip={p:[],uv:[],ix:[]},caps={p:[],uv:[],ix:[]},dense=[];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],n=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/.55));for(let j=0;j<n;j++){const p=[a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n];if(!dense.length||Math.hypot(p[0]-dense.at(-1)[0],p[1]-dense.at(-1)[1])>.001)dense.push(p);}}dense.push(points.at(-1));
function vertex(g,x,z,u,v,cx=x,cz=z){if(options.isWater?.(x,z)){let low=0,high=1;for(let i=0;i<16;i++){const t=(low+high)/2;if(options.isWater(cx+(x-cx)*t,cz+(z-cz)*t))high=t;else low=t;}const t=Math.max(0,low-.015);x=cx+(x-cx)*t;z=cz+(z-cz)*t;}g.p.push(x,height(x,z)+.05,z);g.uv.push(u,v);}
let distance=0;for(let i=1;i<dense.length;i++){const a=dense[i-1],b=dense[i],dx=b[0]-a[0],dz=b[1]-a[1],l=Math.hypot(dx,dz);if(l<.001)continue;const ox=dz/l*width/2,oz=-dx/l*width/2,k=strip.p.length/3;vertex(strip,a[0]-ox,a[1]-oz,0,distance/4,a[0],a[1]);vertex(strip,a[0]+ox,a[1]+oz,1,distance/4,a[0],a[1]);vertex(strip,b[0]-ox,b[1]-oz,0,(distance+l)/4,b[0],b[1]);vertex(strip,b[0]+ox,b[1]+oz,1,(distance+l)/4,b[0],b[1]);strip.ix.push(k,k+2,k+1,k+1,k+2,k+3);distance+=l;}
for(const [x,z] of points){const k=caps.p.length/3;vertex(caps,x,z,.5,.5);for(let j=0;j<=12;j++){const a=j*Math.PI/6;vertex(caps,x+Math.cos(a)*width/2,z+Math.sin(a)*width/2,.5+Math.cos(a)*.5,.5+Math.sin(a)*.5,x,z);if(j)caps.ix.push(k,k+j+1,k+j);}}
const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ct=canvas.getContext('2d');ct.fillStyle=color;ct.fillRect(0,0,128,128);if(width>=1.4){for(const x of[32,89]){const track=ct.createLinearGradient(x-11,0,x+11,0);track.addColorStop(0,'rgba(75,48,29,0)');track.addColorStop(.5,'rgba(75,48,29,.35)');track.addColorStop(1,'rgba(75,48,29,0)');ct.fillStyle=track;ct.fillRect(x-11,0,22,128);}ct.fillStyle='rgba(85,113,53,.38)';ct.fillRect(58,0,12,128);}for(let i=0;i<1500;i++){ct.fillStyle=i%2?'#ba976d':'#604a34';ct.globalAlpha=.16;ct.fillRect((i*43)%128,(i*79)%128,1,1);}const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;tex.wrapS=tex.wrapT=T.RepeatWrapping;
function build(g,radial){g=conformToTerrain(g,height);if(options.isRoadForbidden){const kept=[];for(let i=0;i<g.ix.length;i+=3){const ids=g.ix.slice(i,i+3),v=ids.map(k=>[g.p[k*3],g.p[k*3+2]]);let wet=false;for(let a=0;a<=4&&!wet;a++)for(let b=0;b<=4-a&&!wet;b++){const u=a/4,t=b/4;wet=options.isRoadForbidden(v[0][0]*u+v[1][0]*t+v[2][0]*(1-u-t),v[0][1]*u+v[1][1]*t+v[2][1]*(1-u-t));}if(!wet)kept.push(...ids);}const compact={p:[],uv:[],ix:[]},remap=new Map();for(const old of kept){if(!remap.has(old)){remap.set(old,compact.p.length/3);compact.p.push(...g.p.slice(old*3,old*3+3));compact.uv.push(...g.uv.slice(old*2,old*2+2));}compact.ix.push(remap.get(old));}g=compact;}const geom=new T.BufferGeometry();geom.setAttribute('position',new T.Float32BufferAttribute(g.p,3));geom.setAttribute('uv',new T.Float32BufferAttribute(g.uv,2));geom.setIndex(g.ix);geom.setAttribute('uv1',new T.Float32BufferAttribute(g.p.flatMap((v,i)=>i%3===0?[v/1.8,g.p[i+2]/1.8]:[]),2)); // Normalize winding per triangle; grid hairpins cannot invert the road.
const ix=geom.index,p=geom.attributes.position;for(let i=0;i<ix.count;i+=3){const a=ix.getX(i),b=ix.getX(i+1),c=ix.getX(i+2),ny=(p.getZ(b)-p.getZ(a))*(p.getX(c)-p.getX(a))-(p.getX(b)-p.getX(a))*(p.getZ(c)-p.getZ(a));if(ny<0){ix.setX(i+1,c);ix.setX(i+2,b);}}geom.computeVertexNormals();const data=new Uint8Array(64*64*4);for(let y=0;y<64;y++)for(let x=0;x<64;x++){const d=radial?Math.hypot((x-31.5)/31.5,(y-31.5)/31.5):Math.abs((x-31.5)/31.5),v=Math.round(Math.max(0,Math.min(1,(1-d)*7))*255);data.set([255,v,255,255],(y*64+x)*4);}const alpha=new T.DataTexture(data,64,64);alpha.needsUpdate=true;const m=new T.MeshStandardMaterial({color:'#ffffff',emissive:'#847b63',emissiveIntensity:.035,map:surfaceMap(options.surface|| (points.some(p=>p[1]<-12)?'trail-forest':width<1.5?'trail-hiking':'trail-farm'))||tex,alphaMap:alpha,transparent:true,depthWrite:false,roughness:1,polygonOffset:true,polygonOffsetFactor:-1});const mesh=new T.Mesh(geom,m);mesh.receiveShadow=true;mesh.userData.kind='terrain-path';root.add(mesh);}
build(strip,false);build(caps,true);const stepMat=new T.MeshStandardMaterial({color:'#a7a292',roughness:1});for(let i=1;i<dense.length;i++){const a=dense[i-1],b=dense[i],run=Math.hypot(b[0]-a[0],b[1]-a[1]),rise=Math.abs(height(b[0],b[1])-height(a[0],a[1]));if(run>.08&&rise/run>.7&&!options.isRoadForbidden?.((a[0]+b[0])/2,(a[1]+b[1])/2)){const x=(a[0]+b[0])/2,z=(a[1]+b[1])/2,o=new T.Mesh(new T.BoxGeometry(width*.9,.08,run*.8),stepMat);o.position.set(x,height(x,z)+.06,z);o.rotation.y=Math.atan2(b[0]-a[0],b[1]-a[1]);o.receiveShadow=true;o.castShadow=true;o.userData.kind='trail-stone-step';root.add(o);}}root.userData.path={points,width};return root;}
